-- Materi BUG-17 (Blok 17 Sistem Urogenital): 25 bahasan PDF dalam 5 kelompok.
-- Mengikuti pola impor BRS-13; berkas PDF & gambar halaman sudah ada di storage server.
-- Aman dijalankan pada database kosong (semua INSERT bergantung pada Blok BUG-17 yang ada).

-- Topik lama yang masih terbit (contoh 'Bab 1') disembunyikan, riwayatnya tetap.
UPDATE Topic SET published = false WHERE categoryId = (SELECT id FROM Category WHERE code = 'BUG-17') AND published = true AND id NOT LIKE 'dea-bug17-%';
-- Deskripsi kelas bawaan menyebut kuis per Bab; diganti hanya bila belum diubah admin.
UPDATE Category SET description = 'Blok 17 tahap akademik (preklinik). 25 bahasan sistem urogenital dalam 5 bagian, dari struktur dan fisiologi hingga penyakit serta farmakologi ginjal. Bagian 1 (bahasan 1–5) gratis untuk akun terdaftar.' WHERE code = 'BUG-17' AND description LIKE 'Blok 17 tahap akademik (preklinik). Materi dibagi per Bab%';

INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bug17-group-1', id, 'Struktur Sistem Kemih dan Filtrasi Ginjal', 'Bahasan 1–5. Gratis untuk semua akun terdaftar.', 1, true FROM Category WHERE code = 'BUG-17';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bug17-group-2', id, 'Fungsi Tubulus, Cairan, dan Elektrolit', 'Bahasan 6–10. Tersedia untuk pemilik paket Blok Urogenital atau Basic Medical Science.', 2, true FROM Category WHERE code = 'BUG-17';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bug17-group-3', id, 'Fungsi Ginjal, Pemeriksaan, dan Cedera Akut', 'Bahasan 11–15. Tersedia untuk pemilik paket Blok Urogenital atau Basic Medical Science.', 3, true FROM Category WHERE code = 'BUG-17';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bug17-group-4', id, 'Penyakit Glomerulus, Tubulus, dan Obstruksi', 'Bahasan 16–20. Tersedia untuk pemilik paket Blok Urogenital atau Basic Medical Science.', 4, true FROM Category WHERE code = 'BUG-17';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bug17-group-5', id, 'Infeksi, Tumor, Penyakit Kronik, dan Pencegahan', 'Bahasan 21–25. Tersedia untuk pemilik paket Blok Urogenital atau Basic Medical Science.', 5, true FROM Category WHERE code = 'BUG-17';

